import json
import logging
import os
import sys

from rich.console import Console

logger = logging.getLogger(__name__)

ROUTE_NAMES = [
    "paths.build_url",
    "paths.match",
]


def env_extra_names():
    # Permite agregar nombres desde una variable de entorno separada por comas
    raw = os.environ.get("REPLFORGE_EXTRA_NAMES", "")
    return [name.strip() for name in raw.split(",") if name.strip()]


class ConsoleRunner(Console):
    def auto_names(self):
